-- ============================================================================
-- Prospection 2e lot (2026-08-27) : nouvelles annonces Immobilier (appartements/
-- villas/terrains à louer ou à vendre — PAS des agences) + nouveaux articles
-- Location matériel, sourcés via recherche web (Expat-Dakar, CoinAfrique,
-- recherche site:facebook.com/site:instagram.com), dédupliqués contre
-- prospection/catalogue_immobilier_senegal.csv et catalogue_location_senegal.csv.
-- Même structure que sql/2026_08_12_catalogue_annonces.sql. Idempotent.
--
-- 22/25 annonces Immobilier importées (3 sans prix vérifiable exclues : Villa 8
-- pièces Saly, Terrain 300m² Saly Carrefour, Appartement meublé Liberté 6 Ext. —
-- restent dans le CSV prospection pour relance manuelle, pas de prix inventé).
-- 16/16 articles Location importés ; 10 sans prix ferme passés en "vitrine"
-- (is_vitrine:true dans rental_specs, prix placeholder 1.00€ jamais affiché —
-- même mécanisme que sql/2026_08_12_loueurs_vitrine.sql, PriceDisplay/
-- isVitrineListing affichent "Sur devis").
-- ============================================================================

do $$ begin
  if not exists (select 1 from public.profiles where role='admin') then
    raise exception 'Aucun compte admin (profiles.role=admin) — impossible d''attribuer les annonces.';
  end if;
end $$;

drop table if exists _annonces_b2;
create temp table _annonces_b2(name text, category text, price_eur numeric, description text, image_url text, vendor_name text, is_rental bool, rental_specs jsonb, is_realestate bool, realestate_specs jsonb);

with adm as (select id from public.profiles where role='admin' order by created_at asc limit 1)
select an.name,an.category,an.price_eur,1,an.description,an.image_url,(select id from adm),an.vendor_name,true,an.is_rental,an.rental_specs,an.is_realestate,an.realestate_specs
  from _annonces_b2 an
 where not exists (select 1 from public.products p where p.vendor_id=(select id from adm) and p.name=an.name
     and coalesce(p.is_rental,false)=an.is_rental and coalesce(p.is_realestate,false)=an.is_realestate);

select 'immobilier' as module, count(*) as annonces from _annonces_b2 where is_realestate
 union all select 'location', count(*) from _annonces_b2 where is_rental;
